"""Re-transcribe suspicious Whisper clips and merge replacements."""

from __future__ import annotations

import logging
import re
import shutil
import tempfile
from pathlib import Path
from typing import Any, Callable

from .quality import is_hallucinated_cue, is_phrase_hallucination

_log = logging.getLogger("transub_engine.retranscribe")

ProgressCb = Callable[[dict[str, Any]], None]

# Cap work so a bad VAD run cannot explode wall time.
_MAX_RETRY_CLIPS = 12
_MAX_RETRY_CLIPS_JA_AV = 20

# Pad extracted windows so Whisper has a little context / avoids edge cutoffs.
_EXTRACT_PAD_S = 0.25
# Merge nearby retry ranges into one extract (fewer ffmpeg + Whisper calls).
_MERGE_GAP_S = 0.45

_SOFT_FILLER_HINT = re.compile(
    r"(ありがとうございました|ありがとうございます|ご視聴|チャンネル登録|"
    r"お疲れ様|それではまた|バイバイ|mainly|[A-Za-z]{5,})"
)


def cue_overlaps_clip(cue: dict[str, Any], clip: dict[str, float], *, pad_s: float = 0.15) -> bool:
    c0 = float(cue.get("start") or 0) - pad_s
    c1 = float(cue.get("end") or 0) + pad_s
    s0 = float(clip.get("start") or 0)
    s1 = float(clip.get("end") or 0)
    return c1 > s0 and c0 < s1


def _cue_looks_suspicious_ja_av(cue: dict[str, Any]) -> bool:
    """Extra JA AV signals beyond generic hallucination heuristics."""
    text = str(cue.get("text") or "").strip()
    if not text:
        return True
    if is_phrase_hallucination(text) or is_hallucinated_cue(cue, ja_av=True):
        return True
    if _SOFT_FILLER_HINT.search(text):
        # Politeness / YouTube fillers often appear mid soft-scene as ghosts
        dur = max(0.0, float(cue.get("end") or 0) - float(cue.get("start") or 0))
        if dur <= 2.0 or "ご視聴" in text or "チャンネル" in text:
            return True
    try:
        nsp = cue.get("noSpeechProb")
        if nsp is not None and float(nsp) >= 0.55 and len(text) <= 18:
            return True
        lp = cue.get("avgLogprob")
        if lp is not None and float(lp) < -1.0 and _SOFT_FILLER_HINT.search(text):
            return True
    except (TypeError, ValueError):
        pass
    return False


def _clip_has_text(cues: list[dict[str, Any]], clip: dict[str, float]) -> bool:
    return any(
        str(c.get("text") or "").strip() and cue_overlaps_clip(c, clip) for c in cues
    )


def _neighbor_has_text(
    clips: list[dict[str, float]],
    idx: int,
    cues: list[dict[str, Any]],
    *,
    max_gap_s: float = 1.25,
) -> bool:
    """True if a temporally nearby clip (not merely list-adjacent) has text."""
    cur = clips[idx]
    c0 = float(cur.get("start") or 0)
    c1 = float(cur.get("end") or 0)
    for j, other in enumerate(clips):
        if j == idx:
            continue
        o0 = float(other.get("start") or 0)
        o1 = float(other.get("end") or 0)
        if o1 < c0:
            gap = c0 - o1
        elif c1 < o0:
            gap = o0 - c1
        else:
            gap = 0.0
        if gap <= max_gap_s and _clip_has_text(cues, other):
            return True
    return False


def merge_nearby_clips(
    clips: list[dict[str, float]] | None,
    *,
    max_gap_s: float = _MERGE_GAP_S,
    max_span_s: float = 12.0,
) -> list[dict[str, float]]:
    """Merge adjacent retry windows so one extract covers a cluster."""
    if not clips:
        return []
    ordered = sorted(
        (
            {
                "start": float(c.get("start") or 0),
                "end": float(c.get("end") or 0),
            }
            for c in clips
            if float(c.get("end") or 0) > float(c.get("start") or 0)
        ),
        key=lambda c: (c["start"], c["end"]),
    )
    if not ordered:
        return []
    out: list[dict[str, float]] = [dict(ordered[0])]
    for clip in ordered[1:]:
        prev = out[-1]
        gap = float(clip["start"]) - float(prev["end"])
        span = float(clip["end"]) - float(prev["start"])
        if gap <= max_gap_s and span <= max_span_s:
            prev["end"] = max(float(prev["end"]), float(clip["end"]))
        else:
            out.append(dict(clip))
    return out


def find_clips_needing_retry(
    cues: list[dict[str, Any]] | None,
    clips: list[dict[str, float]] | None,
    *,
    max_clips: int | None = None,
    ja_av: bool = False,
) -> list[dict[str, float]]:
    """
    Select VAD clips that contain hallucinated / empty-overlapping cues.

    Empty clips only retry when a neighbor produced text (avoids re-decoding
    soft non-speech fragments after cleanup). Hallucinated clips are preferred
    over empty ones when the cap is hit.
    """
    if not clips:
        return []
    limit = int(max_clips) if max_clips is not None else (
        _MAX_RETRY_CLIPS_JA_AV if ja_av else _MAX_RETRY_CLIPS
    )
    cues = list(cues or [])
    empty_min = 0.75 if ja_av else 0.8
    scored: list[tuple[int, dict[str, float]]] = []
    seen: set[tuple[float, float]] = set()

    for idx, clip in enumerate(clips):
        start = float(clip.get("start") or 0)
        end = float(clip.get("end") or 0)
        if end <= start:
            continue
        key = (round(start, 3), round(end, 3))
        if key in seen:
            continue
        overlapping = [c for c in cues if cue_overlaps_clip(c, clip)]
        score = 0
        if not overlapping:
            # Empty clip — only retry if long enough and a neighbor has speech
            if (end - start) >= empty_min and _neighbor_has_text(clips, idx, cues):
                score = 40 + min(20, int((end - start) * 4))
        else:
            if ja_av:
                if any(_cue_looks_suspicious_ja_av(c) for c in overlapping):
                    score = 100
            elif any(is_hallucinated_cue(c) for c in overlapping):
                score = 100
            texts = [
                str(c.get("text") or "").strip()
                for c in overlapping
                if str(c.get("text") or "").strip()
            ]
            if len(texts) >= 3 and len(set(t.lower() for t in texts)) == 1:
                score = max(score, 95)
            if ja_av and len(texts) >= 2 and len(set(t.lower() for t in texts)) == 1:
                score = max(score, 90)
        if score > 0:
            seen.add(key)
            scored.append((score, {"start": start, "end": end}))

    scored.sort(key=lambda x: (-x[0], x[1]["start"]))
    selected = [c for _, c in scored[:limit]]
    selected.sort(key=lambda c: c["start"])
    return selected


def merge_cues_replacing_ranges(
    cues: list[dict[str, Any]],
    replacements: list[dict[str, Any]],
    ranges: list[dict[str, float]],
) -> list[dict[str, Any]]:
    """Drop cues overlapping retry ranges, insert replacement cues, sort by start."""
    if not ranges:
        return list(cues or [])
    kept: list[dict[str, Any]] = []
    for cue in cues or []:
        if any(cue_overlaps_clip(cue, r, pad_s=0.05) for r in ranges):
            continue
        kept.append(dict(cue))
    for cue in replacements or []:
        if isinstance(cue, dict) and str(cue.get("text") or "").strip():
            kept.append(dict(cue))
    kept.sort(key=lambda c: float(c.get("start") or 0))
    return kept


def _shift_cues(cues: list[dict[str, Any]], offset_s: float) -> list[dict[str, Any]]:
    off = float(offset_s or 0)
    if abs(off) < 1e-9:
        return [dict(c) for c in cues or []]
    out: list[dict[str, Any]] = []
    for cue in cues or []:
        item = dict(cue)
        item["start"] = float(cue.get("start") or 0) + off
        item["end"] = float(cue.get("end") or 0) + off
        words = cue.get("words")
        if isinstance(words, list):
            shifted_words = []
            for w in words:
                if not isinstance(w, dict):
                    shifted_words.append(w)
                    continue
                ww = dict(w)
                if "start" in ww:
                    ww["start"] = float(ww.get("start") or 0) + off
                if "end" in ww:
                    ww["end"] = float(ww.get("end") or 0) + off
                shifted_words.append(ww)
            item["words"] = shifted_words
        out.append(item)
    return out


def _retranscribe_via_extracts(
    *,
    media_path: str,
    retry_clips: list[dict[str, float]],
    language: str,
    asr_model: str,
    device: str,
    beam_size: int,
    retry_vad: dict[str, Any],
    initial_prompt: str | None,
    hotwords: str | None,
    on_progress: ProgressCb | None,
    should_cancel: Callable[[], bool] | None,
) -> list[dict[str, Any]]:
    """
    Extract short WAV windows and transcribe each once.

    Avoids N× full-media decode (the previous serial clip_timestamps path).
    """
    from .asr.whisper_fw import whisper_transcribe
    from .audio.preprocess import trim_media_window

    windows = merge_nearby_clips(retry_clips)
    replacements: list[dict[str, Any]] = []
    work = Path(tempfile.mkdtemp(prefix="transub_retry_"))
    try:
        for i, clip in enumerate(windows):
            if should_cancel and should_cancel():
                raise RuntimeError("cancelled")
            start = max(0.0, float(clip["start"]) - _EXTRACT_PAD_S)
            end = float(clip["end"]) + _EXTRACT_PAD_S
            if on_progress:
                on_progress(
                    {
                        "stage": "transcribe",
                        "percent": 90 + int(5 * (i / max(len(windows), 1))),
                        "detail": (
                            f"重转写 {i + 1}/{len(windows)} "
                            f"({clip['start']:.1f}-{clip['end']:.1f}s · 切片)"
                        ),
                    }
                )
            try:
                wav = trim_media_window(
                    media_path,
                    start_sec=start,
                    end_sec=end,
                    out_dir=work / f"w{i}",
                )
                part = whisper_transcribe(
                    media_path=wav,
                    language=language,
                    asr_model=asr_model,
                    device=device,
                    beam_size=beam_size,
                    vad_options=retry_vad,
                    clip_timestamps=None,
                    force_no_vad=True,
                    initial_prompt=initial_prompt,
                    hotwords=hotwords,
                    on_progress=None,
                    should_cancel=should_cancel,
                )
                replacements.extend(_shift_cues(part or [], start))
            except Exception as err:
                _log.warning("clip extract-retry failed %s: %s", clip, err)
                continue
    finally:
        shutil.rmtree(work, ignore_errors=True)
    return replacements


def _retranscribe_batched_full(
    *,
    media_path: str,
    retry_clips: list[dict[str, float]],
    language: str,
    asr_model: str,
    device: str,
    beam_size: int,
    retry_vad: dict[str, Any],
    initial_prompt: str | None,
    hotwords: str | None,
    on_progress: ProgressCb | None,
    should_cancel: Callable[[], bool] | None,
) -> list[dict[str, Any]]:
    """Fallback: one Whisper pass on full media with all clip_timestamps."""
    from .asr.whisper_fw import whisper_transcribe

    if on_progress:
        on_progress(
            {
                "stage": "transcribe",
                "percent": 91,
                "detail": f"重转写批量 {len(retry_clips)} 段（整片一次）…",
            }
        )
    return list(
        whisper_transcribe(
            media_path=media_path,
            language=language,
            asr_model=asr_model,
            device=device,
            beam_size=beam_size,
            vad_options=retry_vad,
            clip_timestamps=retry_clips,
            force_no_vad=False,
            initial_prompt=initial_prompt,
            hotwords=hotwords,
            on_progress=None,
            should_cancel=should_cancel,
        )
        or []
    )


def retranscribe_bad_clips(
    *,
    media_path: str,
    cues: list[dict[str, Any]],
    clips: list[dict[str, float]] | None,
    language: str,
    asr_model: str,
    device: str = "auto",
    beam_size: int | None = None,
    vad_options: dict[str, Any] | None = None,
    initial_prompt: str | None = None,
    hotwords: str | None = None,
    on_progress: ProgressCb | None = None,
    should_cancel: Callable[[], bool] | None = None,
    ja_av: bool = False,
) -> tuple[list[dict[str, Any]], int]:
    """
    Re-run Whisper on suspicious clips with stricter settings; merge into cue list.

    Prefer short ffmpeg extracts (one decode per window) over N full-media passes.
    Falls back to a single batched full-media call if extraction is unavailable.

    Returns (merged_cues, retried_clip_count).
    """
    retry_clips = find_clips_needing_retry(cues, clips, ja_av=ja_av)
    if not retry_clips:
        return list(cues or []), 0

    windows = merge_nearby_clips(retry_clips)
    if on_progress:
        on_progress(
            {
                "stage": "transcribe",
                "percent": 90,
                "detail": (
                    f"重转写可疑片段 {len(retry_clips)} 段"
                    f" → {len(windows)} 窗…"
                ),
            }
        )

    # Stricter: higher beam; extracts use force_no_vad (window already speech).
    retry_vad = dict(vad_options or {})
    retry_vad["hallucinationSilenceThreshold"] = (
        retry_vad.get("hallucinationSilenceThreshold") or 2.0
    )
    if ja_av:
        retry_vad["sensitive"] = True
    beam = min(10, max(5, int(beam_size or 5)) + (3 if ja_av else 2))

    replacements: list[dict[str, Any]] = []
    try:
        replacements = _retranscribe_via_extracts(
            media_path=media_path,
            retry_clips=retry_clips,
            language=language,
            asr_model=asr_model,
            device=device,
            beam_size=beam,
            retry_vad=retry_vad,
            initial_prompt=initial_prompt,
            hotwords=hotwords,
            on_progress=on_progress,
            should_cancel=should_cancel,
        )
    except Exception as err:
        _log.warning("extract retranscribe failed, falling back to batched full: %s", err)
        try:
            replacements = _retranscribe_batched_full(
                media_path=media_path,
                retry_clips=retry_clips,
                language=language,
                asr_model=asr_model,
                device=device,
                beam_size=beam,
                retry_vad=retry_vad,
                initial_prompt=initial_prompt,
                hotwords=hotwords,
                on_progress=on_progress,
                should_cancel=should_cancel,
            )
        except Exception as err2:
            _log.warning("batched retranscribe failed: %s", err2)
            replacements = []

    merged = merge_cues_replacing_ranges(cues, replacements, retry_clips)
    return merged, len(retry_clips)
